public sealed class PadRow {public DateTime Day;public string Device,Controller,Button,App;public long Presses;public string Family {get{return PadButtons.Family(Controller,Device);}}}
public partial class MainWindow {
 DispatcherTimer controllerTimer;ComboBox controllerSource;
 void InitControllerRefresh(){controllerTimer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(2)};controllerTimer.Tick+=(s,e)=>ControllerRefreshTick();controllerTimer.Start();}
 IEnumerable<GamepadHeatmap> ControllerMaps(){return page.Children.OfType<Grid>().SelectMany(g=>g.Children.OfType<GamepadHeatmap>());}
 List<PadRow> ControllerRows(){string file=Path.Combine(Store.Root,"gamepad.sqlite");if(!File.Exists(file))return new List<PadRow>();var identities=new PadIdentityRegistry(Path.Combine(Store.Root,PadIdentityRegistry.FileName));using(var db=new Sqlite(file)){return db.Query(mode.SelectedIndex==4?"SELECT * FROM controller_presses WHERE day<=?":"SELECT * FROM controller_presses WHERE day<=? AND day>=?",mode.SelectedIndex==4?new object[]{to.SelectedDate.Value.ToString("yyyy-MM-dd")}:new object[]{to.SelectedDate.Value.ToString("yyyy-MM-dd"),(from.SelectedDate.Value<Store.Period(to.SelectedDate.Value,mode.SelectedIndex)?from.SelectedDate.Value:Store.Period(to.SelectedDate.Value,mode.SelectedIndex)).ToString("yyyy-MM-dd")}).Select(r=>new PadRow{Day=DateTime.Parse(Convert.ToString(r["day"])),Device=identities.Resolve(Convert.ToString(r["device"])),Controller=Convert.ToString(r["controller"]),Button=Convert.ToString(r["button"]),App=Convert.ToString(r["application"]),Presses=(long)Store.Number(r["presses"])}).Where(r=>PadButtons.Countable(r.Button)).ToList();}}
 DataGrid PadTable(IEnumerable rows,string[] props,string[] headers){var table=new DataGrid{IsReadOnly=true,AutoGenerateColumns=false,CanUserAddRows=false,MaxHeight=340,MinHeight=80,ItemsSource=rows,EnableRowVirtualization=true,GridLinesVisibility=DataGridGridLinesVisibility.Horizontal};for(int i=0;i<props.Length;i++)table.Columns.Add(new DataGridTextColumn{Header=headers[i],Binding=new Binding(props[i]),Width=new DataGridLength(1,DataGridLengthUnitType.Star)});return table;}
 void GamepadPage(){
  controllerLayoutKey=ControllerLayoutKey();controllerDeviceRows=new ControllerTableState();controllerButtonRows=new ControllerTableState();controllerAppRows=new ControllerTableState();controllerPlots.Clear();
  if(File.Exists(Path.Combine(NativeRuntime.Base,"visual-fixture.marker")))AddNote("SYNTHETIC TEST DATA – NOT YOUR RECORDS","合成测试数据 · 非真实记录");
  var controls=new WrapPanel{Margin=new Thickness(0,4,0,8)};var start=new Button{Content=T("Start controller collection","开始手柄统计"),Margin=new Thickness(0,0,8,4)};start.Click+=(s,e)=>{NativeRuntime.Start();UpdateControllerPage();};var stop=new Button{Content=T("Pause controller collection","暂停手柄统计"),Margin=new Thickness(0,0,8,4)};stop.Click+=(s,e)=>{NativeRuntime.Stop();UpdateControllerPage();};controls.Children.Add(start);controls.Children.Add(stop);page.Children.Add(controls);
  string selected="both";try{selected=Convert.ToString(Store.ReadJson(Path.Combine(Store.Root,"controller-settings.json"))["mode"]);}catch{}string[] modes={"both","sony","xbox"};controllerSource=new ComboBox{ItemsSource=zh?new[]{"PS + Xbox（含虚拟 Xbox）","仅 PlayStation","仅 Xbox / 映射手柄"}:new[]{"PS + Xbox (including virtual Xbox)","PlayStation only","Xbox / mapped controllers only"},SelectedIndex=Math.Max(0,Array.IndexOf(modes,selected)),MaxWidth=420,HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,0,0,8)};controllerSource.SelectionChanged+=(s,e)=>{string file=Path.Combine(Store.Root,"controller-settings.json"),tmp=file+".ui.tmp";File.WriteAllText(tmp,Store.Json.Serialize(new{mode=modes[controllerSource.SelectedIndex]}));if(File.Exists(file))File.Replace(tmp,file,null);else File.Move(tmp,file);};page.Children.Add(controllerSource);
  AddNote("USB and Bluetooth are supported for both families. Virtual XInput pads count as Xbox. When one PS pad is also exposed as virtual Xbox, select Xbox / mapped only to avoid counting both sources.","两类手柄均支持 USB／蓝牙；虚拟 XInput 归入 Xbox。同一 PS 同时暴露真实与虚拟输入时，选择“仅 Xbox / 映射手柄”可避免两边重复。");
  controllerHealth=Txt("",12);page.Children.Add(controllerHealth);controllerError=Txt("",12);page.Children.Add(controllerError);
  controllerDevicesTable=PadTable(controllerDeviceRows.Rows,new[]{"Controller","Device","Api","Connection","Family","Status","LastButton"},new[]{T("Controller","手柄"),T("Device","设备"),T("Input API","输入接口"),T("Connection","连接方式"),T("Counted under","统计归属"),T("Status","状态"),T("Last button","最后按键")});page.Children.Add(controllerDevicesTable);
  controllerConnectHint=Txt(T("Connect a PS or Xbox controller by USB or Bluetooth to start.","通过 USB 或蓝牙连接 PS / Xbox 手柄即可开始。"),12);page.Children.Add(controllerConnectHint);
  Heading("Button heatmaps · selected period","按键热图 · 当前统计周期");var maps=new Grid();maps.ColumnDefinitions.Add(new ColumnDefinition());maps.ColumnDefinitions.Add(new ColumnDefinition());maps.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});maps.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});var combined=new GamepadHeatmap{Family=GamepadPresentation.Combined};Grid.SetColumnSpan(combined,2);maps.Children.Add(combined);int column=0;foreach(string family in new[]{"PlayStation","Xbox"}){var map=new GamepadHeatmap{Family=family,Margin=new Thickness(column==0?0:6,4,column==0?6:0,8)};Grid.SetRow(map,1);Grid.SetColumn(map,column++);maps.Children.Add(map);}page.Children.Add(maps);
  AddNote("All controllers adds the recorded PS and Xbox counts by matching button position (for example × / A and L1 / LB). Family totals remain available below it.","全部手柄将已记录的 PS 和 Xbox 按对应键位相加（例如 × / A、L1 / LB）；下方保留各类型分项。");
  AddNote("Darker / stronger button color means more presses. Hover for exact counts. Stick presses (L3/R3, LS/RS), D-pad and triggers are counted; stick movement is excluded.","按键颜色越深／越鲜明，次数越多；悬停显示准确次数。摇杆按下（L3/R3、LS/RS）、十字方向键和扳机计数；摇杆摇动不计数。");
  Heading("Press history · date range","按键历史 · 所选日期范围");foreach(string family in new[]{GamepadPresentation.Combined,"PlayStation","Xbox"}){var plot=ControllerPlot(new List<PadRow>(),family);controllerPlots.Add(family,plot);page.Children.Add(plot);}
  AddNote("Total includes action buttons, shoulder buttons and triggers. These bars compare subsets; do not add them to Total again.","总按键已包含动作键、肩键和扳机；各柱为子集比较，不与总按键重复相加。");
  Heading("Buttons by family and device","按类型与设备查看按键");controllerButtonsTable=PadTable(controllerButtonRows.Rows,new[]{"Family","Controller","Device"},new[]{T("Family","类型"),T("Controller","手柄"),T("Device","设备")});var factory=new FrameworkElementFactory(typeof(GamepadButtonIcon));factory.SetBinding(GamepadButtonIcon.ButtonProperty,new Binding("Button"));factory.SetBinding(GamepadButtonIcon.FamilyProperty,new Binding("Family"));controllerButtonsTable.Columns.Add(new DataGridTemplateColumn{Header=T("Button","按键"),CellTemplate=new DataTemplate{VisualTree=factory},Width=90});controllerButtonsTable.Columns.Add(new DataGridTextColumn{Header=T("Presses","次数"),Binding=new Binding("Presses"),Width=100});page.Children.Add(controllerButtonsTable);
  Heading("By application and family","按应用与手柄类型统计");controllerAppsTable=PadTable(controllerAppRows.Rows,new[]{"Family","Application","Presses"},new[]{T("Family","类型"),T("Application","应用"),T("Presses","次数")});page.Children.Add(controllerAppsTable);
  UpdateControllerPage();
 }
 Plot ControllerPlot(List<PadRow> rows,string family){DateTime first=mode.SelectedIndex==4&&rows.Count>0?rows.Min(r=>r.Day):from.SelectedDate.Value;var basis=rows.Select(r=>{var record=new Record{Day=r.Day};record.V["keys"]=r.Presses;return record;}).ToList();var periods=Store.Group(basis,mode.SelectedIndex,first,to.SelectedDate.Value);if(mode.SelectedIndex==0&&periods.Count>10)periods=periods.Skip(periods.Count-10).ToList();var plot=new Plot{Title=GamepadPresentation.Title(family)+T(" · button history"," · 按键历史"),Kind="bars",Stacked=false,MinimumMaximum=4,Unit="count",Labels=periods.Select(r=>Store.Label(r.Day,mode.SelectedIndex)).ToArray()};string[] keys=new string[]{null}.Concat(GamepadPresentation.SummaryIndices.Select(i=>PadButtons.Names[i])).ToArray();Color[] colors={Palette.Parse(family==GamepadPresentation.Combined?"#A178F5":family=="Xbox"?"#12B886":"#5C7CFA"),Palette.Parse("#33BFA0"),Palette.Parse("#F06C82"),Palette.Parse("#55A5F4"),Palette.Parse("#D4A93D"),Palette.Parse("#9A75DF"),Palette.Parse("#D87949"),Palette.Parse("#67A0AB"),Palette.Parse("#A4AD56")};for(int k=0;k<keys.Length;k++){string key=keys[k];var sums=rows.Where(r=>key==null||r.Button==key).GroupBy(r=>Store.Period(r.Day,mode.SelectedIndex)).ToDictionary(g=>g.Key,g=>g.Sum(r=>r.Presses));var series=new Series(key==null?T("Total","总按键"):GamepadPresentation.Label(key,family),periods.Select(r=>sums.ContainsKey(r.Day)?(double)sums[r.Day]:0),colors[k]){IconKey=key!=null&&Array.IndexOf(PadButtons.Names,key)>=4&&Array.IndexOf(PadButtons.Names,key)<=7?key:null,Family=family};plot.Series.Add(series);}return plot;}
 public async Task ControllerExercise(string dir){Directory.CreateDirectory(dir);while(busy||data==null)await Task.Delay(100);var checks=new List<string>();foreach(bool night in new[]{false,true}){dark=night;darkSwitch.IsChecked=night;Theme.Apply(this,night);foreach(int lang in new[]{0,1}){language.SelectedIndex=lang;foreach(int m in new[]{0,1,2,3,4}){mode.SelectedIndex=m;while(busy)await Task.Delay(50);tabs.SelectedIndex=4;Render();UpdateLayout();var plots=page.Children.OfType<Plot>().ToList();if(plots.Count!=3||plots.Any(p=>p.Series.Count!=9||p.Stacked))throw new Exception("Family/action bar separation failed");var maps=ControllerMaps().ToList();if(maps.Count!=3||maps.Any(p=>!p.KeysFit||p.RenderedKeys<24))throw new Exception("Controller button geometry failed");if(plots.Any(p=>p.Series.Skip(1).Any(s=>s.V.Sum()>p.Series[0].V.Sum())))throw new Exception("Action total exceeds total presses");if(maps.Any(p=>p.Counts.Keys.Any(k=>!PadButtons.Countable(k))))throw new Exception("Unknown button included in heatmap");checks.Add("theme="+night+",lang="+lang+",period="+m);}mode.SelectedIndex=0;await Task.Delay(150);tabs.SelectedIndex=4;foreach(double width in new[]{1000.0,1360.0}){Width=width;Render();UpdateLayout();if(ControllerMaps().Any(p=>!p.KeysFit))throw new Exception("Controller clipped at narrow width");await Task.Delay(80);mainScroll.ScrollToTop();await Task.Delay(80);ExportView(Path.Combine(dir,(night?"dark":"light")+(lang==0?"-en":"-zh")+"-"+width+".png"));}mainScroll.ScrollToVerticalOffset(200);await Task.Delay(80);ExportView(Path.Combine(dir,(night?"dark":"light")+(lang==0?"-en":"-zh")+"-heatmaps.png"));mainScroll.ScrollToVerticalOffset(750);await Task.Delay(80);ExportView(Path.Combine(dir,(night?"dark":"light")+(lang==0?"-en":"-zh")+"-bars.png"));}}File.WriteAllText(Path.Combine(dir,"controller-ui-tests.json"),Store.Json.Serialize(new{ok=true,checks=checks}));Close();}
}
